  ('g2-s1-roman_numerals-average-0005', 2, 1, 'roman_numerals', 'average', '{"n": 482}'::jsonb, 'What is 482 written as a Roman numeral?', '["CDXCII", "CDLXXXIII", "CDLXXII", "CDLXXXII"]'::jsonb, 'CDLXXXII', '["off by ten in the numeral''s tens block", "off by ten in the other direction", "off by one, misapplied subtractive notation"]'::jsonb, '482 decomposes into place-value blocks, giving CDLXXXII using subtractive notation where needed.', NULL, '', 30, NULL, 'template-mtap-g2-v1', true),
