  ('g2-s1-roman_numerals-average-0008', 2, 1, 'roman_numerals', 'average', '{"n": 137}'::jsonb, 'What is 137 written as a Roman numeral?', '["CXXVII", "CXLVII", "CXXXVII", "CXXXVIII"]'::jsonb, 'CXXXVII', '["off by ten in the numeral''s tens block", "off by ten in the other direction", "off by one, misapplied subtractive notation"]'::jsonb, '137 decomposes into place-value blocks, giving CXXXVII using subtractive notation where needed.', NULL, '', 30, NULL, 'template-mtap-g2-v1', true),
  ('g2-s1-roman_numerals-difficult-0001', 2, 1, 'roman_numerals', 'difficult', '{"n1": 12, "n2": 4, "op": "-"}'::jsonb, 'What is XII - IV, written as a Roman numeral?', '["IX", "VII", "XVI", "VIII"]'::jsonb, 'VIII', '["off by one after converting back and forth", "off by one in the other direction", "forgot to actually perform the operation"]'::jsonb, 'XII=12, IV=4. 12 - 4 = 8, which is VIII.', NULL, '', 60, NULL, 'template-mtap-g2-v1', true),
  ('g2-s1-roman_numerals-difficult-0002', 2, 1, 'roman_numerals', 'difficult', '{"n1": 7, "n2": 9, "op": "+"}'::jsonb, 'What is VII + IX, written as a Roman numeral?', '["XVI", "XV", "XVII", "VII"]'::jsonb, 'XVI', '["off by one after converting back and forth", "off by one in the other direction", "forgot to actually perform the operation"]'::jsonb, 'VII=7, IX=9. 7 + 9 = 16, which is XVI.', NULL, '', 60, NULL, 'template-mtap-g2-v1', true),
  ('g2-s1-roman_numerals-difficult-0003', 2, 1, 'roman_numerals', 'difficult', '{"n1": 11, "n2": 14, "op": "+"}'::jsonb, 'What is XI + XIV, written as a Roman numeral?', '["XXIV", "XXV", "XI", "XXVI"]'::jsonb, 'XXV', '["off by one after converting back and forth", "off by one in the other direction", "forgot to actually perform the operation"]'::jsonb, 'XI=11, XIV=14. 11 + 14 = 25, which is XXV.', NULL, '', 60, NULL, 'template-mtap-g2-v1', true),
  ('g2-s1-roman_numerals-difficult-0004', 2, 1, 'roman_numerals', 'difficult', '{"n1": 17, "n2": 10, "op": "-"}'::jsonb, 'What is XVII - X, written as a Roman numeral?', '["VII", "XXVII", "VIII", "VI"]'::jsonb, 'VII', '["off by one after converting back and forth", "off by one in the other direction", "forgot to actually perform the operation"]'::jsonb, 'XVII=17, X=10. 17 - 10 = 7, which is VII.', NULL, '', 60, NULL, 'template-mtap-g2-v1', true),
  ('g2-s1-roman_numerals-difficult-0005', 2, 1, 'roman_numerals', 'difficult', '{"n1": 11, "n2": 3, "op": "+"}'::jsonb, 'What is XI + III, written as a Roman numeral?', '["XV", "XI", "XIV", "XIII"]'::jsonb, 'XIV', '["off by one after converting back and forth", "off by one in the other direction", "forgot to actually perform the operation"]'::jsonb, 'XI=11, III=3. 11 + 3 = 14, which is XIV.', NULL, '', 60, NULL, 'template-mtap-g2-v1', true),
  ('g2-s1-roman_numerals-difficult-0006', 2, 1, 'roman_numerals', 'difficult', '{"n1": 23, "n2": 17, "op": "+"}'::jsonb, 'What is XXIII + XVII, written as a Roman numeral?', '["XLI", "XXIII", "XXXIX", "XL"]'::jsonb, 'XL', '["off by one after converting back and forth", "off by one in the other direction", "forgot to actually perform the operation"]'::jsonb, 'XXIII=23, XVII=17. 23 + 17 = 40, which is XL.', NULL, '', 60, NULL, 'template-mtap-g2-v1', true),
  ('g2-s1-roman_numerals-difficult-0007', 2, 1, 'roman_numerals', 'difficult', '{"n1": 10, "n2": 4, "op": "+"}'::jsonb, 'What is X + IV, written as a Roman numeral?', '["XIII", "XIV", "X", "XV"]'::jsonb, 'XIV', '["off by one after converting back and forth", "off by one in the other direction", "forgot to actually perform the operation"]'::jsonb, 'X=10, IV=4. 10 + 4 = 14, which is XIV.', NULL, '', 60, NULL, 'template-mtap-g2-v1', true),
  ('g2-s1-roman_numerals-difficult-0008', 2, 1, 'roman_numerals', 'difficult', '{"n1": 23, "n2": 9, "op": "+"}'::jsonb, 'What is XXIII + IX, written as a Roman numeral?', '["XXIII", "XXXI", "XXXIII", "XXXII"]'::jsonb, 'XXXII', '["off by one after converting back and forth", "off by one in the other direction", "forgot to actually perform the operation"]'::jsonb, 'XXIII=23, IX=9. 23 + 9 = 32, which is XXXII.', NULL, '', 60, NULL, 'template-mtap-g2-v1', true),
