  ('g2-s1-calendar_patterns-easy-0001', 2, 1, 'calendar_patterns', 'easy', '{"start": 3, "n": 5}'::jsonb, 'Today is Thursday. What day of the week will it be 5 days from now?', '["Thursday", "Monday", "Wednesday", "Tuesday"]'::jsonb, 'Tuesday', '["counted one day too many", "counted one day too few", "counted two days too many"]'::jsonb, '5 mod 7 = 5, so count 5 days forward from Thursday to reach Tuesday.', NULL, '', 15, NULL, 'template-mtap-g2-v1', true),
